-- 0.16.0, T179: the indexes of postgres/0065_written_index.sql, for the same reads. SQLite writes no such change (its key writes and adds keep today's path), so they hold none; the reads that would use them run the same.
CREATE INDEX `log_changes_written_idx` ON `log_changes` (`at`,`number`) WHERE (instr("log_changes"."payload", '{"digest":') = 1 AND instr("log_changes"."payload", '"inputs":"') > 0);--> statement-breakpoint
CREATE INDEX `log_changes_written_actor_idx` ON `log_changes` (`actor`,`at`,`number`) WHERE (instr("log_changes"."payload", '{"digest":') = 1 AND instr("log_changes"."payload", '"inputs":"') > 0);--> statement-breakpoint
CREATE INDEX `log_changes_written_environment_idx` ON `log_changes` (json_extract("payload", '$.environmentId'),`at`,`number`) WHERE (instr("log_changes"."payload", '{"digest":') = 1 AND instr("log_changes"."payload", '"inputs":"') > 0);--> statement-breakpoint
CREATE INDEX `log_changes_written_object_idx` ON `log_changes` (`object`,`at`,`number`) WHERE (instr("log_changes"."payload", '{"digest":') = 1 AND instr("log_changes"."payload", '"inputs":"') > 0);--> statement-breakpoint
CREATE INDEX `log_changes_written_actor_environment_idx` ON `log_changes` (`actor`,json_extract("payload", '$.environmentId'),`at`,`number`) WHERE (instr("log_changes"."payload", '{"digest":') = 1 AND instr("log_changes"."payload", '"inputs":"') > 0);--> statement-breakpoint
CREATE INDEX `log_changes_written_actor_object_idx` ON `log_changes` (`actor`,`object`,`at`,`number`) WHERE (instr("log_changes"."payload", '{"digest":') = 1 AND instr("log_changes"."payload", '"inputs":"') > 0);--> statement-breakpoint
CREATE INDEX `log_changes_admitted_idx` ON `log_changes` (`at`,`number`) WHERE (instr("log_changes"."payload", '{"inputs":"') = 1 AND instr("log_changes"."payload", '"op":"member.add"') > 0);--> statement-breakpoint
CREATE INDEX `log_changes_admitted_actor_idx` ON `log_changes` (`actor`,`at`,`number`) WHERE (instr("log_changes"."payload", '{"inputs":"') = 1 AND instr("log_changes"."payload", '"op":"member.add"') > 0);
